{"file_path":"src/lexer.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const sl = line
    const sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          adv()
          adv()
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          adv()
          adv()
        } else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv()
      adv()
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        s += d
      }
      push('rawstring', JSON.stringify(s))
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const run = (ok) => {
        let got = 0
        while (i < n) {
          if (ok(cs[i])) {
            s += adv()
            got++
          } else if (cs[i] === '_' && got > 0 && ok(cs[i - 1]) && ok(cs[i + 1])) {
            s += adv()
          } else break
        }
        return got
      }
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        s += adv()
        s += adv()
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        if (run(ok) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          s += adv()
          run(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2]))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            run(isDigit)
          }
        }
      }
      if (i < n && isIdPart(cs[i])) {
        bad = true
        while (i < n && isIdPart(cs[i])) s += adv()
      }
      if (bad) throw new ScanError(sl, sc, `invalid number ${s}`)
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let s = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const bl = line
        const bc = col
        const d = cs[i]
        if (d === '\n') throw new ScanError(bl, bc, 'newline in string')
        adv()
        if (d === '"') break
        if (d !== '\\') {
          s += d
          continue
        }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') s += '\n'
        else if (e === 't') s += '\t'
        else if (e === 'r') s += '\r'
        else if (e === '\\') s += '\\'
        else if (e === '"') s += '"'
        else if (e === '0') s += '\0'
        else if (e === 'x') {
          if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
          s += String.fromCodePoint(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (!h || cs[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          while (i <= j) adv()
          s += String.fromCodePoint(v)
        } else throw bad()
      }
      push('string', JSON.stringify(s))
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) {
      adv()
      adv()
      push('punct', two)
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      push('punct', c)
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { readFileSync } from 'node:fs'
import { scan, ScanError } from './lexer.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

let out = ''
try {
  const tokens = scan(readFileSync(0, 'utf8'))
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const t of tokens) counts[t.kind]++
    for (const k of Object.keys(counts)) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
  }
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
"}

