      if (v.k === 'err') return v
      const x = toNum(v)
      if (x.k === 'err') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (l.k === 'err') return l
      const r = evalNode(n.r)
      if (r.k === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { k: 'bool', v: res }
      }
      const a = toNum(l), b = toNum(r)
      if (a.k === 'err') return a
      if (b.k === 'err') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        case '^': return fin(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const name = n.name
  const argc = n.args.length
  if (name === 'IF') {
    if (argc !== 3) return err('#ERR!')
    if (n.args.some((a) => a.type === 'range')) return err('#ERR!')
    const c = evalNode(n.args[0])
    if (c.k === 'err') return c
    let t
    if (c.k === 'bool') t = c.v
    else if (c.k === 'num') t = c.v !== 0
    else return err('#VALUE!')
    return evalNode(n.args[t ? 1 : 2])
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS'].includes(name)) return err('#NAME?')
  if (name === 'ABS' && argc !== 1) return err('#ERR!')
  const vals = []
  for (const a of n.args) {
    if (a.type === 'range') {
      const x = parseAddr(a.a), y = parseAddr(a.b)
      if (!x || !y) return err('#REF!')
      for (const c of rangeCells(x, y)) {
        const v = cellValue(c.key)
        if (v.k === 'err') return v
        vals.push(v)
      }
    } else {
      const v = evalNode(a)
      if (v.k === 'err') return v
      vals.push(v)
    }
  }
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
  if (name === 'ABS' && vals.length !== 1) return err('#ERR!')
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'ABS': return num(Math.abs(nums[0]))
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
  }
  return err('#ERR!')
}

function show(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const key of sorted) {
  const c = cells.get(key)
  const name = addrName(c.col, c.row)
  if (mode === 'values') out.push(`${name}=${show(cellValue(key))}`)
  else {
    let line = name + ':'
    if (c.content[0] === '=') {
      const t = parse(c.content.slice(1))
      if (t) {
        const set = new Map()
        collect(t, set)
        for (const a of [...set.values()].sort((x, y) => x.key - y.key)) line += ' ' + addrName(a.col, a.row)
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
