cat > src/parse.js <<'EOF'
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue
    const f = raw.split(/\s+/)
    const fail = (m) => ({ error: `line ${i + 1}: ${m}` })
    const num = (field, s, least) => {
      if (!INT.test(s) || BigInt(s) < BigInt(least)) return null
      return BigInt(s)
    }
    const d = f[0]
    if (d === 'bucket' || d === 'window') {
      const n = d === 'bucket' ? 5 : 4
      if (f.length !== n) {
        return fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (events.length) return fail('declarations must come before the first event')
      if (!NAME.test(f[1])) return fail(`invalid policy name ${f[1]}`)
      const specs = d === 'bucket'
        ? [['capacity', 1], ['refill', 0], ['per', 1]]
        : [['limit', 0], ['span', 1]]
      const vals = []
      for (let k = 0; k < specs.length; k++) {
        const v = num(specs[k][0], f[k + 2], specs[k][1])
        if (v === null) return fail(`${specs[k][0]} must be an integer of at least ${specs[k][1]}`)
        vals.push(v)
      }
      if (policies.has(f[1])) return fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { type: d, name: f[1], vals })
    } else if (d === 'route') {
      if (f.length < 3) return fail('expected route <prefix> <policy>...')
      if (events.length) return fail('declarations must come before the first event')
      if (!NAME.test(f[1])) return fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) return fail(`prefix ${f[1]} is routed twice`)
      for (const p of f.slice(2)) if (!policies.has(p)) return fail(`unknown policy ${p}`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (f.length !== 3) return fail('expected event <tick> <key>')
      const t = num('tick', f[1], 0)
      if (t === null) return fail('tick must be an integer of at least 0')
      if (!NAME.test(f[2])) return fail(`invalid key ${f[2]}`)
      if (lastTick !== null && t < lastTick) return fail(`tick ${f[1]} is before tick ${lastTick}`)
      lastTick = t
      events.push({ tick: t, key: f[2] })
    } else {
      return fail(`unknown directive ${d}`)
    }
  }
  return { routes, events }
}
EOF
cat > src/sim.js <<'EOF'
function makeState(p, tick) {
  if (p.type === 'bucket') {
    const [cap, refill, per] = p.vals
    // tokens are held in units of 1/per
    let units = cap * per
    let last = tick
    return {
      advance(t) {
        units += refill * (t - last)
        if (units > cap * per) units = cap * per
        last = t
      },
      ok: () => units >= per,
      record: () => { units -= per },
    }
  }
  const [limit, span] = p.vals
  let ticks = []
  return {
    advance(t) { ticks = ticks.filter((x) => x > t - span) },
    ok: () => BigInt(ticks.length) < limit,
    record: (t) => { ticks.push(t) },
  }
}

export function simulate({ routes, events }, mode) {
  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denier = null
