function makeState(p, tick) {
  if (p.type === 'bucket') {
    const [cap, refill, per] = p.vals
    // tokens are held in units of 1/per
    let units = cap * per
    let last = tick
    return {
      advance(t) {
        units += refill * (t - last)
        if (units > cap * per) units = cap * per
        last = t
      },
      ok: () => units >= per,
      record: () => { units -= per },
    }
  }
  const [limit, span] = p.vals
  let ticks = []
  return {
    advance(t) { ticks = ticks.filter((x) => x > t - span) },
    ok: () => BigInt(ticks.length) < limit,
    record: (t) => { ticks.push(t) },
  }
}

export function simulate({ routes, events }, mode) {
  const prefixes = [...routes.keys()]
  const states = new Map()
  const stats = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denier = null
    if (best !== null) {
      const pols = routes.get(best)
      const sts = pols.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, makeState(p, tick))
        return states.get(id)
      })
      sts.forEach((s) => s.advance(tick))
      for (let i = 0; i < sts.length; i++) {
        if (!sts[i].ok()) { denier = pols[i].name; break }
      }
      if (denier === null) sts.forEach((s) => s.record(tick))
    }
    const s = stats.get(key) || { a: 0, d: 0 }
    stats.set(key, s)
    if (denier === null) { s.a++; ta++ } else { s.d++; td++ }
    if (mode === 'replay') out += `${tick} ${key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
  }
  if (mode === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
  return out
}
