#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { readFileSync } from 'node:fs'
import { parseElection } from './parse.js'
import { count } from './count.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

let election
try {
  election = parseElection(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.election) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

const { rounds, winner } = count(election)
let out = ''
if (mode === 'rounds') {
  rounds.forEach((r, i) => {
    out += `round ${i + 1}: ${r.lines.map(([n, v]) => `${n}=${v}`).concat(`exhausted=${r.exhausted}`).join(' ')}\n`
    if (r.eliminated !== null) out += `eliminated ${r.eliminated}\n`
  })
} else {
  out += `rounds ${rounds.length}\n`
}
out += winner === null ? 'no winner\n' : `winner ${winner}\n`
process.stdout.write(out)
EOF
cat > src/parse.js <<'EOF'
const NAME = /^[A-Za-z0-9_-]+$/

function fail(msg) {
  const e = new Error(msg)
  e.election = true
  throw e
}

export function parseElection(text) {
  const lines = text.split('\n')
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const n = i + 1
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (word === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const total = ballots.reduce((s, b) => s + b.count, 0n)
  const history = []
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const lines = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = { lines, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [name, v] of lines) if (v * 2n > active) return { rounds, winner: name }
    let tied = [...continuing]
    const min = lines[lines.length - 1][1]
    tied = tied.filter((c) => votes.get(c) === min)
    for (let r = 0; tied.length > 1 && r < history.length; ) {
      const vs = tied.map((c) => history[r].get(c))
      const m = vs.reduce((a, b) => (a < b ? a : b))
      if (vs.every((v) => v === m)) { r++; continue }
      tied = tied.filter((c) => history[r].get(c) === m)
      r = 0
    }
    tied.sort()
    const out = tied[tied.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
