class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

