    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const d = this.s[this.i]
      if (d === undefined) fail('unterminated string')
      this.i++
      if (d === '"') out += '"'
      else if (d === '\\') out += '\\'
      else if (d === 'n') out += '\n'
      else if (d === 't') out += '\t'
      else if (d === 'r') out += '\r'
      else if (d === '0') out += '\0'
      else if (d === 'u') {
