export class UriError extends Error {}

export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]*):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    r.authority = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const rb = hp.lastIndexOf(']')
  const c = hp.indexOf(':', rb < 0 ? 0 : rb)
  if (c < 0) return { userinfo, host: hp, port: null }
  return { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const bad = /%(?![0-9A-Fa-f]{2})/
