export function normalize(r, lineNo) {
  let parts = null
  if (r.authority !== null) parts = splitAuthority(r.authority)
  const checks = [
    ['path', r.path],
    ['userinfo', parts && parts.userinfo],
    ['host', parts && parts.host],
    ['query', r.query],
    ['fragment', r.fragment],
