const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = (k = 1) => {
    for (let j = 0; j < k; j++) {
      const c = cs[i++]
      if (c === '\n') { line++; col = 1 }
      else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
      else col++
    }
  }
  // position of index `to` relative to current state, without advancing
  const posAt = (to) => {
    const sl = line, sc = col, si = i
    adv(to - i)
    const r = [line, col]
    line = sl; col = sc; i = si
    return r
  }

  const digits = (isD) => {
    // consume a run of digits with single underscores between digits; returns end index
    let j = i
    while (j < n) {
      if (isD(cs[j])) j++
      else if (cs[j] === '_' && j > i && isD(cs[j - 1]) && isD(cs[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
