      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      let depth = 0
      while (i < n) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; adv(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; adv(2); if (depth === 0) break }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    const sl = line, sc = col
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(cs.slice(i + 2, j).join('')) })
      adv(j + 1 - i)
