      let bad = false
      const p = cs[i + 1]
      let isD = null
      if (c === '0' && (p === 'x' || p === 'X')) isD = isHex
      else if (c === '0' && (p === 'b' || p === 'B')) isD = isBin
      else if (c === '0' && (p === 'o' || p === 'O')) isD = isOct
      const save = i
      if (isD) {
