const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim()
    if (t === '' || t[0] === '#') continue
    const f = t.split(/\s+/)
    const fail = (r) => ({ error: `error: line ${i + 1}: ${r}` })
    const num = (field, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) return fail(`${field} must be an integer of at least ${least}`)
      return null
    }
    const d = f[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      if (f.length !== (isB ? 5 : 4)) {
        return fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (events.length) return fail('declarations must come before the first event')
      if (!NAME.test(f[1])) return fail(`invalid policy name ${f[1]}`)
      const spec = isB ? [['capacity', 1], ['refill', 0], ['per', 1]] : [['limit', 0], ['span', 1]]
      for (let k = 0; k < spec.length; k++) {
        const e = num(spec[k][0], f[2 + k], spec[k][1])
        if (e) return e
      }
      if (policies.has(f[1])) return fail(`policy ${f[1]} is declared twice`)
      const v = f.slice(2).map(BigInt)
      policies.set(f[1], isB ? { name: f[1], kind: 'b', cap: v[0], refill: v[1], per: v[2], st: new Map() }
        : { name: f[1], kind: 'w', limit: v[0], span: v[1], st: new Map() })
    } else if (d === 'route') {
      if (f.length < 3) return fail('expected route <prefix> <policy>...')
      if (events.length) return fail('declarations must come before the first event')
      if (!NAME.test(f[1])) return fail(`invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) return fail(`prefix ${f[1]} is routed twice`)
      for (const p of f.slice(2)) if (!policies.has(p)) return fail(`unknown policy ${p}`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else if (d === 'event') {
      if (f.length !== 3) return fail('expected event <tick> <key>')
      const e = num('tick', f[1], 0)
      if (e) return e
      if (!NAME.test(f[2])) return fail(`invalid key ${f[2]}`)
      const tick = BigInt(f[1])
      if (lastTick !== null && tick < lastTick) return fail(`tick ${f[1]} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, tickStr: f[1], key: f[2] })
    } else {
      return fail(`unknown directive ${d}`)
    }
  }
  return { routes, events }
}

function advance(p, key, tick) {
  let s = p.st.get(key)
  if (p.kind === 'b') {
    if (!s) {
      s = { units: p.cap * p.per, last: tick }
      p.st.set(key, s)
    } else {
      const max = p.cap * p.per
      s.units += p.refill * (tick - s.last)
      if (s.units > max) s.units = max
      s.last = tick
    }
  } else {
    if (!s) { s = { ticks: [] }; p.st.set(key, s) }
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
  return s
}

function run({ routes, events }, mode) {
  const out = []
  const per = new Map()
  let ta = 0
  let td = 0
  for (const ev of events) {
    let best = null
    for (const pre of routes.keys()) {
      if (ev.key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    }
    let denier = null
    if (best !== null) {
      const ps = routes.get(best)
      const sts = ps.map((p) => advance(p, ev.key, ev.tick))
      for (let i = 0; i < ps.length && !denier; i++) {
        const p = ps[i]
        const ok = p.kind === 'b' ? sts[i].units >= p.per : BigInt(sts[i].ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (!denier) {
        ps.forEach((p, i) => {
          if (p.kind === 'b') sts[i].units -= p.per
          else sts[i].ticks.push(ev.tick)
        })
      }
    }
    const c = per.get(ev.key) || { a: 0, d: 0 }
    per.set(ev.key, c)
    if (denier) { c.d++; td++ } else { c.a++; ta++ }
    if (mode === 'replay') out.push(`${ev.tickStr} ${ev.key} ${denier ? 'deny ' + denier : 'allow'}`)
  }
  if (mode === 'summary') {
    for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
    }
    out.push(`total allowed=${ta} denied=${td}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

module.exports = { parse, run }
