}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'err', e })
const num = (v) => ({ t: 'num', v })
const ZERO = num(0)

function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, key: letters + row }
}

// ---- sheet parsing
