    return v.t === 'err' ? v : num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = args.flatMap(argValues)
  const e = vals.find((v) => v.t === 'err')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'AVG': return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
  }
}

function fmt(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)) + 0)
    case 'err': return v.e
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
let out = ''
for (const c of sorted) {
  if (mode === 'values') {
    out += `${c.addr.key}=${fmt(cellValue(c.addr.key))}\n`
  } else {
    const m = new Map()
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) names(ast, m)
    }
    const list = [...m.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.addr.key}:${list.map((a) => ' ' + a.key).join('')}\n`
  }
}
process.stdout.write(out)
